    F1: accepted(numberedCandidates[0]) ? numberedCandidates[0] : missing(),
    F2: accepted(numberedCandidates[1]) ? numberedCandidates[1] : missing(),
    F3: accepted(numberedCandidates[2]) ? numberedCandidates[2] : missing(),
